/**
 * Cathedral editor (Element 3 + 4 from CATHEDRAL_DECISIONS.md).
 *
 * Wraps Pi's `CustomEditor` with cathedral chrome **without replacing it**.
 * Pi's editor stays in charge of:
 *   - text layout + cursor positioning (CURSOR_MARKER preserved)
 *   - autocomplete dropdown (slash commands, agents, file mentions)
 *   - multi-line wrap + scroll indicators
 *   - bracketed paste, IME, kill-ring, history
 *
 * We just decorate around it: replace Pi's flat top/bottom horizontal lines
 * with our `┌─ LABEL ──┐` splash or unlabeled active `┌──┐` / `└─┘` corners, wrap each interior row in side
 * pipes, paint the inner span with the recess background, and let any
 * autocomplete rows tail through unwrapped (they sit under the bottom
 * border like a dropdown).
 *
 * Splash state (no messages):
 *   ┌─ DIVINE INVOCATION ──────────────────────────────────┐
 *   │ > Ask anything... "Refactor the auth flow."  █       │
 *   └──────────────────────────────────────────────────────┘
 *
 * Active state (after first message):
 *   ┌──────────────────────────────────────────────────────┐
 *   │ > /ag<cursor>                                        │
 *   └──────────────────────────────────────────────────────┘
 *      ▸ /agent  switch agent
 *      ▸ /agents list available agents
 *
 * Earlier versions of this file *replaced* `super.render` entirely on
 * splash. That broke slash-command autocomplete (typing `/res` showed no
 * suggestions) because Pi's autocomplete machinery is part of `super.render`.
 * The wrap approach below keeps autocomplete alive.
 */

import type {
	ExtensionAPI,
	ExtensionContext,
	KeybindingsManager,
} from "@earendil-works/pi-coding-agent";
import { CustomEditor } from "@earendil-works/pi-coding-agent";
import { CURSOR_MARKER, truncateToWidth, visibleWidth, type EditorTheme, type TUI } from "@earendil-works/pi-tui";
import { sessionHasMessages as cachedSessionHasMessages } from "../session-cache.js";
import { activeThemeColors } from "../themes/index.js";
import { EditorImageDraftState, isLikelyClipboardImagePath, normalizePastedImagePath, setActiveEditorDraftController } from "./editor-draft-state.js";
import {
	INPUT_FRAME_LABEL_ACTIVE,
	INPUT_FRAME_LABEL_SPLASH,
	INPUT_FRAME_PLACEHOLDER,
} from "./input-frame.js";
export { normalizeRawMultilinePasteInput } from "./multiline-paste.js";
import { countLegacyModifierEnterPresses, CSI_U_SHIFT_ENTER, normalizeRawMultilinePasteInput } from "./multiline-paste.js";

const RESET = "\u001b[0m";
const RESET_FG = "\u001b[39m";
// oxlint-disable-next-line no-control-regex -- intentional ESC byte match for terminal control sequences
const ANSI_PATTERN = /\u001b\[[0-9;]*m/g;
const SPLASH_INPUT_FRAME_WIDTH = 60;
const RAW_PASTE_CR_WINDOW_MS = 50;
const ACTIVE_AUTOCOMPLETE_LEFT_OFFSET = 4; // `│ > ` before typed content.

function visibleLength(text: string): number {
	return visibleWidth(text);
}

function ellipsize(text: string, max: number): string {
	if (max <= 0) return "";
	if (text.length <= max) return text;
	if (max === 1) return "…";
	return `${text.slice(0, max - 1)}…`;
}

function fitAnsiToWidth(text: string, width: number): string {
	if (width <= 0) return "";
	return visibleLength(text) > width ? truncateToWidth(text, width, "…") : text;
}

function fg(hex: string): string {
	const n = hex.replace("#", "");
	const r = Number.parseInt(n.slice(0, 2), 16);
	const g = Number.parseInt(n.slice(2, 4), 16);
	const b = Number.parseInt(n.slice(4, 6), 16);
	return `\u001b[38;2;${r};${g};${b}m`;
}

function bg(hex: string): string {
	const n = hex.replace("#", "");
	const r = Number.parseInt(n.slice(0, 2), 16);
	const g = Number.parseInt(n.slice(2, 4), 16);
	const b = Number.parseInt(n.slice(4, 6), 16);
	return `\u001b[48;2;${r};${g};${b}m`;
}

function color(text: string, hex: string): string {
	return `${fg(hex)}${text}${RESET}`;
}

type EditorSkillColors = { readonly accent: string };
type EditorRowUnit = { readonly raw: string; readonly visible: string };
const INLINE_SKILL_TOKEN = /(?:^|(?<=\s))\/skill:([A-Za-z0-9][A-Za-z0-9_-]*)/g;

function splitEditorRowUnits(row: string): EditorRowUnit[] {
	const units: EditorRowUnit[] = [];
	for (let index = 0; index < row.length;) {
		if (row.startsWith(CURSOR_MARKER, index)) {
			units.push({ raw: CURSOR_MARKER, visible: "" });
			index += CURSOR_MARKER.length;
			continue;
		}
		if (row[index] === "\u001b") {
			if (row[index + 1] === "[") {
				let end = index + 2;
				while (end < row.length && !/[\x40-\x7e]/.test(row[end]!)) end += 1;
				end = Math.min(row.length, end + 1);
				units.push({ raw: row.slice(index, end), visible: "" });
				index = end;
				continue;
			}
			// Preserve non-CSI terminal controls (OSC/APC) atomically through ST.
			const st = row.indexOf("\u001b\\", index + 2);
			const end = st === -1 ? Math.min(row.length, index + 2) : st + 2;
			units.push({ raw: row.slice(index, end), visible: "" });
			index = end;
			continue;
		}
		const glyph = String.fromCodePoint(row.codePointAt(index)!);
		units.push({ raw: glyph, visible: glyph });
		index += glyph.length;
	}
	return units;
}

/**
 * Decorate the complete `/skill:name` token in Pi's rendered editor row with
 * the Cathedral accent. Visible characters and columns remain unchanged, so
 * cursor/layout math stays owned by Pi.
 *
 * CathedralEditor is a legacy ANSI wrapper around Pi's byte-rendered editor;
 * typed Cathedral primitives are not appropriate at this compatibility seam.
 */
export type EditorSkillSourceRange = { readonly start: number; readonly end: number };
export type EditorSkillSourceLayout = {
	readonly text: string;
	readonly rows: readonly EditorSkillSourceRange[];
};

export function formatInlineSkillRowsForEditor(
	rows: readonly string[],
	colors: EditorSkillColors = { accent: activeThemeColors().accent },
	source?: EditorSkillSourceLayout,
): string[] {
	const parsed = rows.map((row) => {
		const units = splitEditorRowUnits(row);
		return { row, units, visible: units.map((unit) => unit.visible).join("") };
	});
	let fallbackOffset = 0;
	const sourceRows = source?.rows ?? parsed.map((row) => {
		const range = { start: fallbackOffset, end: fallbackOffset + row.visible.length };
		fallbackOffset = range.end;
		return range;
	});
	const sourceText = source?.text ?? parsed.map((row) => row.visible).join("");
	if (!sourceText.includes("/skill:")) return [...rows];
	const tokenRanges = [...sourceText.matchAll(INLINE_SKILL_TOKEN)].map((match) => ({
		start: match.index,
		end: match.index + match[0].length,
	}));
	if (tokenRanges.length === 0) return [...rows];
	const accentedByRow = sourceRows.map((row) => {
		const accented = new Set<number>();
		for (const token of tokenRanges) {
			const start = Math.max(row.start, token.start);
			const end = Math.min(row.end, token.end);
			for (let index = start; index < end; index += 1) accented.add(index - row.start);
		}
		return accented;
	});

	return parsed.map(({ units }, rowIndex) => {
		const accented = accentedByRow[rowIndex] ?? new Set<number>();
		let output = "";
		let visibleIndex = 0;
		let accentActive = false;
		for (const unit of units) {
			if (unit.visible.length === 0) {
				output += unit.raw;
				if (unit.raw === RESET) accentActive = false;
				continue;
			}
			const desired = accented.has(visibleIndex);
			if (desired !== accentActive) {
				// Reset only foreground when leaving the token. A full SGR reset
				// would cancel Pi's inverse fallback cursor when it follows directly.
				output += desired ? fg(colors.accent) : RESET_FG;
				accentActive = desired;
			}
			output += unit.raw;
			// Regex match indices are UTF-16 offsets; keep astral graphemes aligned.
			visibleIndex += unit.visible.length;
		}
		if (accentActive) output += RESET_FG;
		return output;
	});
}

export function formatInlineSkillTokensForEditor(
	row: string,
	colors: EditorSkillColors = { accent: activeThemeColors().accent },
): string {
	return formatInlineSkillRowsForEditor([row], colors)[0] ?? row;
}

function dividerFg(): string {
	return fg(activeThemeColors().divider);
}

function recessBg(): string {
	return bg(activeThemeColors().surfaceRecess);
}

const RESET_BG = "\u001b[49m";

function withFrameBackground(line: string): string {
	// Any nested RESET clears the background. Re-apply the frame background so
	// the whole input frame row remains the recessed #120D0A Bible well.
	const frameBg = recessBg();
	return `${frameBg}${line.replaceAll(RESET, `${RESET}${frameBg}`)}${RESET_BG}`;
}

function maybeWithFrameBackground(line: string, enabled: boolean): string {
	return enabled ? withFrameBackground(line) : line;
}

/**
 * Build the cathedral top border with an optional embedded label. V2 active
 * input is label-less; splash uses `DIVINE INVOCATION`.
 */
function renderTopBorder(width: number, label: string | undefined, paintBackground: boolean): string {
	if (width < 6) return maybeWithFrameBackground(color("─".repeat(width), activeThemeColors().divider), paintBackground);
	const inner = width - 2;
	if (!label) return maybeWithFrameBackground(color(`┌${"─".repeat(inner)}┐`, activeThemeColors().divider), paintBackground);
	const leftDashes = "─".repeat(Math.min(1, inner));
	const maxLabelText = Math.max(0, inner - leftDashes.length - 2); // 2 = spaces around label
	const labelText = ellipsize(label, maxLabelText);
	const labelInner = labelText.length > 0 ? ` ${labelText} ` : "";
	const rightDashes = "─".repeat(Math.max(0, inner - leftDashes.length - labelInner.length));
	const divider = dividerFg();
	const left = `${divider}┌${leftDashes}`;
	const labelSegment = color(labelInner, activeThemeColors().accent);
	const right = `${divider}${rightDashes}┐${RESET}`;
	return maybeWithFrameBackground(`${left}${labelSegment}${right}`, paintBackground);
}

function renderBottomBorder(width: number, paintBackground: boolean): string {
	if (width < 6) return maybeWithFrameBackground(color("─".repeat(width), activeThemeColors().divider), paintBackground);
	return maybeWithFrameBackground(color(`└${"─".repeat(width - 2)}┘`, activeThemeColors().divider), paintBackground);
}

/**
 * Wrap a single Pi editor row in `│ <inner> │` with the recess background
 * painted across the whole row. The inner span is `width - 2` cells wide;
 * we pad with spaces to that exact width so the bg block is uniform.
 *
 * IMPORTANT: We must not strip ANSI from `inner` — it carries cursor markers
 * and color codes that Pi's TUI engine relies on (CURSOR_MARKER for hardware
 * cursor placement, syntax/highlight colors, etc.). We just measure visible
 * length to compute padding.
 */
function wrapRow(inner: string, width: number, paintBackground: boolean): string {
	const innerWidth = Math.max(0, width - 2);
	const fitted = fitAnsiToWidth(inner, innerWidth);
	const visible = visibleLength(fitted);
	const pad = Math.max(0, innerWidth - visible);
	const padded = `${fitted}${" ".repeat(pad)}`;
	const divider = dividerFg();
	return maybeWithFrameBackground(`${divider}│${RESET}${padded}${divider}│${RESET}`, paintBackground);
}

/**
 * Wrap a Pi editor row with the V2 active prompt: `│ > <content>│`. The
 * `>` is accent-colored on the first content row and replaced with three
 * spaces on continuation rows so multi-line input keeps cursor columns aligned.
 */
function wrapActiveRow(inner: string, width: number, paintBackground: boolean, isFirstRow: boolean): string {
	const innerWidth = Math.max(0, width - 2);
	const promptCells = 3; // " > " or "   "
	const contentWidth = Math.max(0, innerWidth - promptCells);
	const fitted = fitAnsiToWidth(inner, contentWidth);
	const visible = visibleLength(fitted);
	const pad = Math.max(0, contentWidth - visible);
	const padded = `${fitted}${" ".repeat(pad)}`;
	const prompt = isFirstRow
		? ` ${color(">", activeThemeColors().accent)} `
		: "   ";
	const divider = dividerFg();
	return maybeWithFrameBackground(`${divider}│${RESET}${prompt}${padded}${divider}│${RESET}`, paintBackground);
}

function centerRow(row: string, width: number): string {
	const visible = visibleLength(row);
	if (visible > width) return truncateToWidth(row, width, "…");
	if (visible === width) return row;
	const left = Math.floor((width - visible) / 2);
	const right = width - visible - left;
	return `${" ".repeat(left)}${row}${" ".repeat(right)}`;
}

export function alignAutocompleteRow(row: string, width: number, options: { splash: boolean; frameWidth?: number }): string {
	if (width <= 0) return "";
	const left = options.splash
		? Math.min(
			Math.max(0, Math.floor((width - Math.min(width, options.frameWidth ?? width)) / 2) + 1),
			Math.max(0, width - 1),
		)
		: Math.min(ACTIVE_AUTOCOMPLETE_LEFT_OFFSET, Math.max(0, width - 1));
	const frameContentWidth = options.splash ? Math.max(0, Math.min(width, options.frameWidth ?? width) - 2) : undefined;
	const available = Math.max(0, Math.min(width - left, frameContentWidth ?? width));
	const fitted = fitAnsiToWidth(row, available);
	const pad = Math.max(0, width - left - visibleLength(fitted));
	return `${" ".repeat(left)}${fitted}${" ".repeat(pad)}`;
}

/**
 * Test whether a row is one of Pi's flat horizontal borders, i.e. a row
 * consisting of nothing but `─` chars (after stripping ANSI), or one of
 * Pi's scroll indicators like `─── ↑ N more ───────`.
 */
function isPiBorderRow(row: string): boolean {
	const stripped = row.replace(ANSI_PATTERN, "").trimEnd();
	if (stripped.length === 0) return false;
	if (/^─+$/.test(stripped)) return true;
	// Scroll indicators: `─── ↑ 3 more ───────────`
	if (/^─+\s*[↑↓]\s*\d+\s*more\s*─+$/.test(stripped)) return true;
	return false;
}

export interface CathedralEditorOptions {
	readonly isSplash?: () => boolean;
}

export class CathedralEditor extends CustomEditor {
	private lastPrintableInputAt = 0;
	private readonly imageDraftState = new EditorImageDraftState();
	private submitHandler: ((text: string) => void) | undefined;

	constructor(
		private readonly cathedralTui: TUI,
		theme: EditorTheme,
		keybindings: KeybindingsManager,
		private readonly isSplash: () => boolean,
	) {
		super(cathedralTui, theme, keybindings);
		// Shadow pi-tui Editor's private handlePaste with the image-collapsing
		// interceptor (see cathedralHandlePaste's doc comment).
		// SAFETY: shadowing pi-tui Editor's private handlePaste; instance property wins over the base method at runtime.
		unsafeCast<{ handlePaste: (text: string) => void }>(this).handlePaste = this.cathedralHandlePaste;
		// SAFETY: deleting the inherited optional onSubmit so the defineProperty getter below is the sole owner.
		delete (this as { onSubmit?: unknown }).onSubmit;
		Object.defineProperty(this, "onSubmit", {
			configurable: true,
			get: () => this.submitHandler,
			set: (handler: ((text: string) => void) | undefined) => {
				this.submitHandler = handler
					? (text: string) => {
						handler(this.imageDraftState.expandTokensToPaths(text));
						this.imageDraftState.clear();
					}
					: undefined;
			},
		});
		setActiveEditorDraftController({
			hasDraft: () => this.getText().length > 0,
			clearDraft: () => {
				this.setText("");
				this.imageDraftState.clear();
				this.cathedralTui.requestRender();
			},
		});
	}

	override insertTextAtCursor(text: string): void {
		if (this.collapseImagePath(text)) return;
		super.insertTextAtCursor(text);
	}

	/**
	 * Collapse a pasted/dropped image path into an `[Image N]` token. Returns
	 * true when the text was consumed. Candidates are normalized first
	 * (surrounding quotes stripped, `\ ` escapes unescaped) so terminal
	 * drag/paste forms of paths with spaces still collapse and the draft
	 * state stores the real on-disk path.
	 */
	/**
	 * Expand `[Image N]` draft tokens to their temp-file paths WITHOUT clearing
	 * the draft state. Used by queue-time consumers (Alt+Enter follow-up
	 * queueing) that must capture real paths before the editor is cleared, but
	 * only commit the clear once the queue accepts the message — a busy→idle
	 * race can decline the queue, and clearing early would leave dangling
	 * tokens in the editor. The Enter-submit wrapper above stays atomic
	 * (expand + clear).
	 */
	public expandDraftTokens(text: string): string {
		return this.imageDraftState.expandTokensToPaths(text);
	}

	/** Commit-side of {@link expandDraftTokens}: clear the image draft state. */
	public clearImageDrafts(): void {
		this.imageDraftState.clear();
	}

	private collapseImagePath(text: string): boolean {
		const candidate = normalizePastedImagePath(text);
		if (!isLikelyClipboardImagePath(candidate)) return false;
		const token = this.imageDraftState.addImage(candidate);
		super.insertTextAtCursor(token);
		this.cathedralTui.requestRender();
		return true;
	}

	/**
	 * Bracketed-paste interception. Terminal paste (Cmd+V) and file drops
	 * arrive as bracketed paste and flow through pi-tui `Editor.handlePaste`
	 * → `insertTextAtCursorInternal`, BYPASSING the public
	 * `insertTextAtCursor` override above — so image paths pasted that way
	 * splattered as raw text. `handlePaste` is declared private in pi-tui's
	 * d.ts but is a regular prototype method at runtime; this instance
	 * property shadows it (`this.handlePaste(...)` inside Editor.handleInput
	 * resolves to the instance property first). Kept as an assigned arrow
	 * rather than a method declaration because TypeScript refuses subclass
	 * overrides of private-declared members.
	 */
	private readonly cathedralHandlePaste = (pastedText: string): void => {
		if (this.collapseImagePath(pastedText)) return;
		// SAFETY: delegating to pi-tui Editor's private handlePaste through its structural prototype shape.
		unsafeCast<{ handlePaste(text: string): void }>(CustomEditor.prototype).handlePaste.call(this, pastedText);
	};

	override handleInput(data: string): void {
		const now = Date.now();
		if (data === "\r" && now - this.lastPrintableInputAt <= RAW_PASTE_CR_WINDOW_MS) {
			super.handleInput("\n");
			return;
		}

		// Legacy modifier-Enter (shift+enter / alt+enter / ctrl+j without the
		// kitty keyboard protocol) → deterministic newline. See
		// countLegacyModifierEnterPresses for the transport matrix and the
		// \x1b\r ambiguity decision. One press per handleInput call — pi-tui
		// parses chunks as single keys.
		const presses = countLegacyModifierEnterPresses(data);
		if (presses > 0) {
			for (let press = 0; press < presses; press += 1) super.handleInput(CSI_U_SHIFT_ENTER);
			return;
		}

		const normalized = normalizeRawMultilinePasteInput(data);
		// oxlint-disable-next-line no-control-regex -- intentional control-byte range check for printable input
		if (/[^\x00-\x1f\x7f]/.test(normalized)) this.lastPrintableInputAt = now;
		super.handleInput(normalized);
		this.imageDraftState.pruneMissingTokens(this.getText());
		this.maybeTriggerMidLineSlashMenu(data);
	}

	/**
	 * pi-tui auto-triggers the slash menu only when "/" starts the message; a
	 * "/" typed after whitespace MID-sentence never opens it. Its trigger-
	 * character API explicitly rejects "/", so nudge the private trigger
	 * directly (same precedent as the handlePaste shadow above). This only
	 * OPENS the menu — serving mid-line command suggestions is the
	 * autocomplete provider's job (see rpc/editor.ts); providers without
	 * mid-line support return null and the nudge is a harmless no-op.
	 * A "/" inside a token (e.g. "src/foo") does not trigger: the character
	 * before it must be whitespace.
	 */
	private maybeTriggerMidLineSlashMenu(data: string): void {
		if (data !== "/") return;
		// SAFETY: reading pi-tui Editor's private autocomplete internals through a structural seam.
		const internals = unsafeCast<{ autocompleteState: unknown; tryTriggerAutocomplete(explicitTab?: boolean): void }>(this);
		if (internals.autocompleteState) return;
		const { line, col } = this.getCursor();
		const textBeforeCursor = (this.getText().split("\n")[line] ?? "").slice(0, col);
		if (!textBeforeCursor.endsWith("/")) return;
		const beforeSlash = textBeforeCursor.slice(0, -1);
		if (beforeSlash.length === 0) return; // line start — pi-tui's own trigger owns it
		const boundary = beforeSlash[beforeSlash.length - 1];
		if (boundary !== " " && boundary !== "\t") return;
		internals.tryTriggerAutocomplete();
	}

	private visibleRowSourceRanges(layoutWidth: number, visibleRowCount: number): readonly EditorSkillSourceRange[] {
		// Compatibility seam: consume Pi Editor.layoutText's exact FULL logical
		// layout, then project source offsets through scrollOffset. Layout chunks
		// are contiguous slices of each logical line, including atomic paste-marker
		// handling, so no private pi-tui module import or duplicate wrap algorithm is
		// needed (peer-only extension installs cannot resolve deep package imports).
		// SAFETY: consuming pi-tui Editor.layoutText via its documented private shape (compat seam above).
		const internals = unsafeCast<{
			scrollOffset: number;
			layoutText(width: number): Array<{ text: string }>;
		}>(this);
		const layoutRows = internals.layoutText(layoutWidth);
		const allRanges: EditorSkillSourceRange[] = [];
		let layoutIndex = 0;
		let lineOffset = 0;
		for (const line of this.getLines()) {
			let lineIndex = 0;
			do {
				const chunk = layoutRows[layoutIndex++];
				if (!chunk) break;
				const end = Math.min(line.length, lineIndex + chunk.text.length);
				allRanges.push({ start: lineOffset + lineIndex, end: lineOffset + end });
				lineIndex = end;
				// Defensive progress if a future Pi layout emits an empty chunk for a
				// non-empty line. Styling degrades for that line instead of looping.
				if (chunk.text.length === 0 && line.length > 0) lineIndex = line.length;
			} while (lineIndex < line.length);
			lineOffset += line.length + 1; // include the hard newline between logical lines
		}
		return allRanges.slice(internals.scrollOffset, internals.scrollOffset + visibleRowCount);
	}

	override render(width: number): string[] {
		// Too narrow for our chrome — fall back to Pi's bare render.
		if (width < 8) return super.render(width);

		const splash = this.isSplash();
		const frameWidth = splash ? Math.min(width, SPLASH_INPUT_FRAME_WIDTH) : width;

		// Active state reserves 3 inner cols for the V2 `│ > ` prompt so cathedral
		// chrome owns the prompt arrow + leading space. Splash keeps the historical
		// budget so the ghost placeholder fits the exact 60-col mockup width.
		const piContentWidth = splash ? frameWidth - 2 : frameWidth - 5;
		const innerRows = super.render(Math.max(1, piContentWidth));
		if (innerRows.length === 0) return innerRows;

		const fullRow = (row: string): string => splash ? centerRow(row, width) : row;
		const label = splash ? INPUT_FRAME_LABEL_SPLASH : INPUT_FRAME_LABEL_ACTIVE;
		const paintFrameBackground = !splash;

		// Find Pi's bottom border row. Pi's render is structured:
		//   row 0           : top border (─...─)
		//   rows 1..k-1     : content rows
		//   row k           : bottom border
		//   rows k+1..end   : autocomplete dropdown (if any)
		let bottomIdx = -1;
		for (let i = 1; i < innerRows.length; i++) {
			if (isPiBorderRow(innerRows[i]!)) {
				bottomIdx = i;
				break;
			}
		}

		// Splash placeholder injection: when the editor is empty AND we're on
		// splash, replace the (otherwise blank) content row with the placeholder
		// text so the user sees what the input wants. Pi's editor
		// has no concept of placeholders; we shim it from the outside.
		const text = this.getText();
		const showPlaceholder = splash && text.length === 0;
		const lastContentIdx = bottomIdx === -1 ? innerRows.length : bottomIdx;
		const contentRows = innerRows.slice(1, lastContentIdx);
		const visibleSourceRanges = this.visibleRowSourceRanges(Math.max(1, piContentWidth - 1), contentRows.length);
		const decoratedContentRows = showPlaceholder
			? contentRows
			: formatInlineSkillRowsForEditor(contentRows, undefined, { text, rows: visibleSourceRanges });
		const renderContent = (row: string, isFirstContent: boolean): string => {
			if (showPlaceholder && isFirstContent) {
				// Preserve Pi's zero-width cursor marker while painting our ghost text.
				// Without this, TUI.positionHardwareCursor() sees no marker on the
				// splash empty state and emits \x1b[?25l after every render.
				const prompt = ` ${color(">", activeThemeColors().accent)} ${CURSOR_MARKER}`;
				const maxPlaceholder = Math.max(0, frameWidth - 2 - visibleLength(prompt));
				const placeholder = ellipsize(INPUT_FRAME_PLACEHOLDER, maxPlaceholder);
				const ghost = `${prompt}${color(placeholder, activeThemeColors().foregroundDim)}`;
				return fullRow(wrapRow(ghost, frameWidth, paintFrameBackground));
			}
			if (!splash) return wrapActiveRow(row, frameWidth, paintFrameBackground, isFirstContent);
			return fullRow(wrapRow(row, frameWidth, paintFrameBackground));
		};

		const result: string[] = [fullRow(renderTopBorder(frameWidth, label, paintFrameBackground))];

		let contentSeen = false;
		for (const row of decoratedContentRows) {
			result.push(renderContent(row, !contentSeen));
			contentSeen = true;
		}
		result.push(fullRow(renderBottomBorder(frameWidth, paintFrameBackground)));

		// Autocomplete rows after Pi's bottom border — passed through as-is
		// at the narrower inner width. They appear as a dropdown directly
		// below the cathedral frame's bottom border, matching how Pi already
		// renders autocomplete (and how the Stitch mockup for the active
		// state implies suggestions float below the input).
		if (bottomIdx !== -1) {
			for (let i = bottomIdx + 1; i < innerRows.length; i++) {
				// Pi emits autocomplete rows relative to its bare editor at column 0.
				// Cathedral chrome adds a left frame + prompt (`│ > `) in active mode
				// and centers the splash frame, so dropdown rows need the same anchor
				// translation or slash-command suggestions appear glued to terminal col 0.
				result.push(alignAutocompleteRow(innerRows[i]!, width, { splash, frameWidth }));
			}
		}

		return result;
	}
}

export function createCathedralEditor(
	tui: TUI,
	theme: EditorTheme,
	keybindings: KeybindingsManager,
	options: CathedralEditorOptions = {},
): CathedralEditor {
	return new CathedralEditor(tui, theme, keybindings, options.isSplash ?? (() => false));
}

function sessionHasMessages(ctx: ExtensionContext): boolean {
	try {
		return cachedSessionHasMessages(ctx);
	} catch {
		return false;
	}
}

/**
 * Mount the cathedral editor via setEditorComponent. Replaces Pi's default
 * editor with our wrapper that decorates `super.render` output without
 * intercepting any of its behaviour (autocomplete, multi-line, IME etc.
 * all keep working).
 */
/**
 * Structural re-cast for private pi-tui Editor internals. A plain `as` chain is
 * rejected by TypeScript (private members block comparability) and by lint, so
 * the conversion goes through an opaque generic boundary instead.
 */
function unsafeCast<T>(...[value]: [unknown]): T {
	// SAFETY: callers pass structural views verified against the pi-tui version pinned in peerDependencies.
	return value as T;
}

export function installCathedralEditor(pi: ExtensionAPI): void {
	pi.on("session_start", (_event, ctx) => {
		if (!ctx.hasUI) return;
		// Pi 0.71+ exposes the current editor factory. Read it before installing
		// ours so future editor composition work has a safe public seam and repeated
		// session_start calls can observe whether another extension already owns it.
		// SAFETY: probing pi-tui ui internals not present in the public ExtensionUI type.
		(ctx.ui as { getEditorComponent?: () => void }).getEditorComponent?.();
		ctx.ui.setEditorComponent((tui, theme, keybindings) => {
			return createCathedralEditor(tui, theme, keybindings, { isSplash: () => !sessionHasMessages(ctx) });
		});
	});
}
